import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.Bum8orMG.js";const u=JSON.parse('{"title":"Roadmap","description":"Delivery phases and exit criteria for Katana UI.","frontmatter":{"title":"Roadmap","description":"Delivery phases and exit criteria for Katana UI."},"headers":[],"relativePath":"ui-kit/roadmap.md","filePath":"ui-kit/roadmap.md","lastUpdated":1790432985000}'),l={name:"ui-kit/roadmap.md"};function o(r,a,n,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Delivery is phased so each stage is usable on its own. The toolkit keeps shipping independently; the kit never blocks core releases.</p><h2 id="phase-0-—-foundations" tabindex="-1">Phase 0 — Foundations <a class="header-anchor" href="#phase-0-—-foundations" aria-label="Permalink to &quot;Phase 0 — Foundations&quot;">​</a></h2><ul><li>[ ] Token contract (<code>--kt-*</code> variables) with light and dark values.</li><li>[ ] Headless primitives: disclosure, focus trap, popover positioning, roving tabindex.</li><li>[ ] Theming bridge over <code>ThemeService</code>.</li><li>[ ] Foundation component example end to end.</li><li>[ ] Docs skeleton and a11y checklist.</li></ul><p><strong>Exit criteria:</strong> a themed button and modal work in vanilla, Vue/Nuxt and Astro with keyboard support and no SSR errors.</p><h2 id="phase-1-—-shells-and-layouts" tabindex="-1">Phase 1 — Shells and layouts <a class="header-anchor" href="#phase-1-—-shells-and-layouts" aria-label="Permalink to &quot;Phase 1 — Shells and layouts&quot;">​</a></h2><ul><li>[ ] App shell (sidebar, topbar, breadcrumbs, command palette).</li><li>[ ] Auth shell, settings shell and marketing shell.</li><li>[ ] The 50 common layout examples.</li></ul><p><strong>Exit criteria:</strong> every layout renders in light/dark and passes the a11y checklist.</p><h2 id="phase-2-—-core-pages" tabindex="-1">Phase 2 — Core pages <a class="header-anchor" href="#phase-2-—-core-pages" aria-label="Permalink to &quot;Phase 2 — Core pages&quot;">​</a></h2><ul><li>[ ] Four auth pages and profile settings.</li><li>[ ] Eight dashboard layouts with chart blocks and data tables.</li><li>[ ] Support/FAQ page.</li></ul><p><strong>Exit criteria:</strong> dashboards run against mock Safe Result contracts with loading, empty and error states.</p><h2 id="phase-3-—-applications" tabindex="-1">Phase 3 — Applications <a class="header-anchor" href="#phase-3-—-applications" aria-label="Permalink to &quot;Phase 3 — Applications&quot;">​</a></h2><ul><li>[ ] E-commerce pages (10).</li><li>[ ] File manager and Agentic Storage UI.</li><li>[ ] Chat app on <code>AssistantService</code>.</li><li>[ ] Gen-AI app (home, images, content creator, library).</li></ul><p><strong>Exit criteria:</strong> each app works end to end with the toolkit services and no custom data layer.</p><h2 id="phase-4-—-blocks-and-interactions" tabindex="-1">Phase 4 — Blocks and interactions <a class="header-anchor" href="#phase-4-—-blocks-and-interactions" aria-label="Permalink to &quot;Phase 4 — Blocks and interactions&quot;">​</a></h2><ul><li>[ ] 15+ ready-to-use UI blocks.</li><li>[ ] 100+ interaction examples with plugin integrations.</li><li>[ ] ApexCharts adapter plus the SVG fallback.</li></ul><p><strong>Exit criteria:</strong> every example is documented, keyboard-operable and covered by the metadata registry.</p><h2 id="phase-5-—-distribution-and-llm-files" tabindex="-1">Phase 5 — Distribution and LLM files <a class="header-anchor" href="#phase-5-—-distribution-and-llm-files" aria-label="Permalink to &quot;Phase 5 — Distribution and LLM files&quot;">​</a></h2><ul><li>[ ] Publish <code>@katanakit/ui</code> with per-component entry points.</li><li>[ ] Tailwind and daisyUI presets.</li><li>[ ] Six curated themes.</li><li>[ ] Generate <code>llms.txt</code>, <code>llms-full.txt</code> and <code>registry.json</code> in CI.</li></ul><p><strong>Exit criteria:</strong> a fresh project installs the package, picks a theme and scaffolds a block using only the LLM files.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guides/roadmap">Toolkit roadmap</a> — core services and adapters.</li><li><a href="./inventory">Inventory</a> — the full planned surface.</li></ul>',22)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
